function lowpass(fs, fc) {
  return [0.5176381928, 0.7071067812, 1.9318516526].map((q) => {
    const w = (2 * Math.PI * fc) / fs
    const c = Math.cos(w)
    const al = Math.sin(w) / (2 * q)
    const a0 = 1 + al
    return [(1 - c) / 2 / a0, (1 - c) / a0, (1 - c) / 2 / a0, (-2 * c) / a0, (1 - al) / a0, 0, 0]
  })
}
